import {utilityTrendSnapshot} from './utility-trends.js?v=power-overload-grace-1';
export function cityGrowthTargets(c){return [5000,20000,25000].map(population=>({population,done:c.stats.population>=population}));}
export function cityGrowthGuide(c){const n=v=>Math.round(v||0).toLocaleString('en-US'),u=utilityTrendSnapshot(c),backlog=c.stats.uncollectedWaste||0;return `<details><summary>From town to city · ${n(c.stats.population)} / 25,000 residents</summary><p>Use these practice milestones to plan the next expansion. They describe your population now and can become incomplete if residents leave.</p><ol>${cityGrowthTargets(c).map(t=>`<li>${t.done?'✓ ':''}<strong>${n(t.population)} residents</strong></li>`).join('')}</ol><p><strong>Grow in stages.</strong> Start with connected homes, shops and industry. Add water before raising density, and expand workplaces alongside housing. High-density zoning alone cannot overcome weak demand or low land value.</p><p><strong>Make room for taller buildings.</strong> Parks, healthy roads, low pollution and effective public safety help land value. Separate polluting industry from homes and offices. Check Zone development to see what blocks each neighborhood.</p><p><strong>Keep infrastructure ahead of growth.</strong> Citywide spare electricity: ${n(u.powerAvailable-u.powerDemand)} units; spare water: ${n(u.waterAvailable-u.waterDemand)}. These totals do not guarantee service across disconnected networks. Add supply before building out another district.</p><p><strong>Plan beyond landfill.</strong> Uncollected garbage: ${n(backlog)} units. ${backlog?'Clear the backlog before expanding; garbage can lower land value and empty buildings.':'Keep checking disposal as the population grows.'} Landfills fill over time. Recycling, incineration, waste-to-energy or neighbor exports can support continued growth.</p><p><strong>Protect the budget and review rewards.</strong> Treasury: §${n(c.funds)}; current monthly balance: §${n(c.stats.balance)}. Build in affordable stages and review Rewards as your population rises. If homes stop growing, check residential capacity as well as local services and demand.</p></details>`;}
